\usepackage{tikz}
\usepackage{tikz-3dplot}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\usepgfplotslibrary{colormaps}
\pgfplotsset{standard 3d/.style={
    axis lines=center, width=8cm, height=8cm,
    xmin=-1.5, xmax=1.5, ymin=-1.5, ymax=1.5, zmin=0, zmax=2.2,
    ticks=none, view={115}{20},
    xlabel style={at={(ticklabel* cs:1)},anchor=north west},
    ylabel style={at={(ticklabel* cs:1)},anchor=south west},
    zlabel style={at={(ticklabel* cs:1)},anchor=south}}}
\usetikzlibrary{arrows.meta,calc,decorations.markings,decorations.pathreplacing}
\usetikzlibrary{positioning,matrix,arrows,shapes,decorations,shadows,fadings,patterns}

